INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15901, 'Proverbs 17:16', 'Proverbs', 17, 16, '&nbsp;په کم عقل د خرچې کولو څۀ فائده نشته، ځکه چې هغه په خپله د عقل زده کولو خواهش نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15902, 'Proverbs 17:17', 'Proverbs', 17, 17, '&nbsp;دوست په هر وخت کښې مينه کوى، او ورور هغه دے چې په مصيبت کښې په کار راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15903, 'Proverbs 17:18', 'Proverbs', 17, 18, '&nbsp;څوک چې کم عقل وى خپل لاس د ګاونډى په ځائ په ضمانت کښې بل له ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15904, 'Proverbs 17:19', 'Proverbs', 17, 19, '&nbsp;هر هغه څوک چې د جنګ جګړو سره مينه کوى د ګناه سره مينه کوى، هر هغه څوک چې په لوړه ګرځى نو تباهۍ له دعوت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15905, 'Proverbs 17:20', 'Proverbs', 17, 20, '&nbsp;هر څوک چې بد ګُمانه وى نو هغه به برکت ونۀ مومى، د چا ژبه چې دوکه ماره وى په مصيبت کښې به راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15906, 'Proverbs 17:21', 'Proverbs', 17, 21, '&nbsp;د چا په کور کښې چې بې‌وقوفه زوئ پېدا شى نو په کور کښې غم او پرېشانۍ راولى، د بې‌وقوفه د پلار دپاره خوشحالى نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15907, 'Proverbs 17:22', 'Proverbs', 17, 22, '&nbsp;خوشحاله زړۀ د ټول بدن دپاره ښۀ دوائى ده، خو مات زړۀ هډُوکى هم اوچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15908, 'Proverbs 17:23', 'Proverbs', 17, 23, '&nbsp;بدکاران په پټه رشوت اخلى د اِنصاف په لاره کښې دوئ مداخلت پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15909, 'Proverbs 17:24', 'Proverbs', 17, 24, '&nbsp;د يو پوهه انسان مقصد د عقل حاصلول وى، خو د بې‌وقوفه لټون بې‌مقصده وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15910, 'Proverbs 17:25', 'Proverbs', 17, 25, '&nbsp;کم عقل زوئ د خپل پلار د غم باعث وى، او د تريخوالى باعث د هغه چا دپاره وى د چا نه چې پېدا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15911, 'Proverbs 17:26', 'Proverbs', 17, 26, '&nbsp;يو بې‌ګناه له سزا ورکول ښۀ خبره نۀ ده، او نۀ يو شريف له د هغۀ د شرافت په وجه کوړې ورکول ښۀ خبره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15912, 'Proverbs 17:27', 'Proverbs', 17, 27, '&nbsp;يو هوښيار ډيرې کمې خبرې کوى، او يو پوهه کس نرمې خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15913, 'Proverbs 17:28', 'Proverbs', 17, 28, '&nbsp;تر دې چې يو کم عقل هم هوښيار ګڼلے شى کله چې دے غلے وى، او تميزدار ښکارى کۀ چرې دے خپله خولۀ بنده ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15914, 'Proverbs 18:1', 'Proverbs', 18, 1, '&nbsp;بې‌خونده کس هر څۀ د خپلې خوښې په مطابق کوى، او د هرې صحيح فېصلې مخالفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15915, 'Proverbs 18:2', 'Proverbs', 18, 2, '&nbsp;کم عقل د پوهې نه خوند نۀ شى اخستے، خو هغه په خپلو نظريو څرګندولو خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15916, 'Proverbs 18:3', 'Proverbs', 18, 3, '&nbsp;کله چې بدکارى راشى نو رسوائى هم راځى، او د شرم سره سپکوالے راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15917, 'Proverbs 18:4', 'Proverbs', 18, 4, '&nbsp;د انسان د خولې خبرې لکه ژورې اوبۀ دى، او د حِکمت چينه لکه بهېدونکې وله ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15918, 'Proverbs 18:5', 'Proverbs', 18, 5, '&nbsp;دا ښۀ خبره نۀ ده چې د مجرم طرفدارے وشى يا بې‌ګناه د اِنصاف نه محروم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15919, 'Proverbs 18:6', 'Proverbs', 18, 6, '&nbsp;د کم عقل خبرې جنګ جوړوى، او خپل ځان وهلو ته جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15920, 'Proverbs 18:7', 'Proverbs', 18, 7, '&nbsp;د کم عقل خولۀ د هغۀ خپله تباهى ده، او د هغۀ خبرې د هغۀ د خپل ځان دام دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15921, 'Proverbs 18:8', 'Proverbs', 18, 8, '&nbsp;د غېبت کوونکى خبرې لکه د خوندور خوراک په شان وى، دا بلکل د سړى دننه بدن ته کوزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15922, 'Proverbs 18:9', 'Proverbs', 18, 9, '&nbsp;څوک چې په خپل کار کښې سست وى هغه لکه د هغه ورور په شان دے څوک چې تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15923, 'Proverbs 18:10', 'Proverbs', 18, 10, '&nbsp;د مالِک خُدائ نوم مضبوطه قلعه ده، صادقان هلته منډه وهى او په حفاظت کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15924, 'Proverbs 18:11', 'Proverbs', 18, 11, '&nbsp;د مالداره دولت د هغوئ دپاره د مضبوط ښار په شان وى او په دې خيال چې دا به د هغوئ د حفاظت يو اوچت دېوال وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15925, 'Proverbs 18:12', 'Proverbs', 18, 12, '&nbsp;د تباهۍ نه وړاندې د انسان زړۀ کښې کبر وى، خو د عزت نه وړاندې عاجزى راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15926, 'Proverbs 18:13', 'Proverbs', 18, 13, '&nbsp;څوک چې د خبرې اورېدو نه مخکښې جواب ورکوى، دا د هغۀ کم عقلتوب دے او د هغۀ شرم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15927, 'Proverbs 18:14', 'Proverbs', 18, 14, '&nbsp;د انسان روح بيمارى هم برداشت کولے شى، خو مات روح به څوک وزغمى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15928, 'Proverbs 18:15', 'Proverbs', 18, 15, '&nbsp;هوښياران تل د عِلم حاصلولو په لټون کښې وى، او د هغوئ غوږونه د عِلم زده کولو دپاره تيار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15929, 'Proverbs 18:16', 'Proverbs', 18, 16, '&nbsp;تحفه د انسان دپاره لار خلاصوى، او د هغۀ لاس تر غټو خلقو پورې رسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15930, 'Proverbs 18:17', 'Proverbs', 18, 17, '&nbsp;څوک چې په عدالت کښې خپله دعوىٰ اول پېش کړى نو هغه صحيح ښکارى ترڅو چې بل څوک راشى او هغۀ نه تپوسونه شروع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15931, 'Proverbs 18:18', 'Proverbs', 18, 18, '&nbsp;په پچې اچولو جنګونه ختميږى، او د مضبوطو مخالفينو په مينځ کښې جنګ ختموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15932, 'Proverbs 18:19', 'Proverbs', 18, 19, '&nbsp;د يو خفه شوى ورور رضا کول د يو مضبوط ښار د فتح کولو نه سخت وى، او لانجې د قلعې دروازو ته اړمونه اچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15933, 'Proverbs 18:20', 'Proverbs', 18, 20, '&nbsp;د خپلې خولې په مېوه انسان خپله خېټه مړه کړى او د خپلو شونډو په فصل هغه مطمئن شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15934, 'Proverbs 18:21', 'Proverbs', 18, 21, '&nbsp;په ژبه کښې د مرګ او ژوند طاقت شته دے، او څوک چې دې سره مينه کوى هغوئ ته به يې نتيجه مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15935, 'Proverbs 18:22', 'Proverbs', 18, 22, '&nbsp;چا ته چې ښۀ ښځه مِلاو شوه دا د هغۀ دپاره خزانه ده، او هغه ورته د مالِک خُدائ د خوا نه برکت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15936, 'Proverbs 18:23', 'Proverbs', 18, 23, '&nbsp;غريب سړے د رحم دپاره مِنت زارى کوى، خو مالداره سړے په سختۍ سره جواب ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15937, 'Proverbs 18:24', 'Proverbs', 18, 24, '&nbsp;ځينې دوستان يو بل ته کنده کنى، خو رښتينے دوست د خپل ورور نه هم وفادار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15938, 'Proverbs 19:1', 'Proverbs', 19, 1, '&nbsp;دا بهتره ده چې يو سړے غريب وى او په ايماندارۍ سره ژوند تېروى، د هغه چا نه چې دروغژن او کم عقل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15939, 'Proverbs 19:2', 'Proverbs', 19, 2, '&nbsp;د عِلم نه بغېر جذبات څرګندول ښۀ نۀ دى، او بې‌صبرى لار خطا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15940, 'Proverbs 19:3', 'Proverbs', 19, 3, '&nbsp;د انسان کم عقلتوب د هغۀ ژوند تباه کوى، او بيا د هغۀ تريخوالے د مالِک خُدائ خلاف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15941, 'Proverbs 19:4', 'Proverbs', 19, 4, '&nbsp;دولت ډېر دوستان پېدا کوى، خو غربت ټول دوستان د هغۀ نه شړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15942, 'Proverbs 19:5', 'Proverbs', 19, 5, '&nbsp;دروغژن ګواه به د سزا نه نۀ بچ کيږى، او څوک چې دروغ وائى هغه به بچ پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15943, 'Proverbs 19:6', 'Proverbs', 19, 6, '&nbsp;ډېر خلق د حاکِم خوشامندى کوى، او هر څوک د هغه چا دوست وى څوک چې تُحفې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15944, 'Proverbs 19:7', 'Proverbs', 19, 7, '&nbsp;کۀ د غريب سړى نه د هغۀ رشته‌دار ډډه کوى، نو بيا به د هغۀ دوستان د هغۀ نه څومره نور هم ډډه کوى. کۀ څۀ هم چې هغه د هغوئ سره د خبرو کولو کوشش کوى، خو هغوئ ترې نه لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15945, 'Proverbs 19:8', 'Proverbs', 19, 8, '&nbsp;څوک چې حِکمت حاصلوى نو د خپل ځان سره مينه کوى، څوک چې پوهه خوښوى هغۀ ته برکت ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15946, 'Proverbs 19:9', 'Proverbs', 19, 9, '&nbsp;دروغژن ګواه به د سزا نه نۀ بچ کيږى، او څوک چې دروغ وائى هغه به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15947, 'Proverbs 19:10', 'Proverbs', 19, 10, '&nbsp;کم عقل سره عېش عشرت ښۀ نۀ ښکارى، او دا به لا څومره نامناسبه وى کۀ چرې يو غلام په شهزادګانو حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15948, 'Proverbs 19:11', 'Proverbs', 19, 11, '&nbsp;د انسان حِکمت د هغۀ غصه قابو کوى، او د بل بد ځان ته نۀ ودرول هغۀ ته عزت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15949, 'Proverbs 19:12', 'Proverbs', 19, 12, '&nbsp;د بادشاه غصه د ازمرى د غړمبېدو په شان وى، خو د هغۀ احسان لکه په کبل د پرخې په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15950, 'Proverbs 19:13', 'Proverbs', 19, 13, '&nbsp;بې‌وقوفه زوئ د پلار د تباهۍ باعث وى، او جګړماره ښځه داسې وى لکه کوټه چې هر وخت راڅاڅى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15951, 'Proverbs 19:14', 'Proverbs', 19, 14, '&nbsp;انسان ته په وراثت کښې کورونه او دولت د پلار نيکۀ نه ملاويږى، خو هوښياره ښځه صرف هغۀ ته د مالِک خُدائ د طرفه ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15952, 'Proverbs 19:15', 'Proverbs', 19, 15, '&nbsp;ناراستى ښۀ خوب راولى، او لټ سړے اوږے پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15953, 'Proverbs 19:16', 'Proverbs', 19, 16, '&nbsp;څوک چې د خُدائ حُکمونه منى نو هغه د خپل ژوند حفاظت کوى، خو هغه څوک چې د هغۀ د لارو لا پرواهى کوى هغه به مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15954, 'Proverbs 19:17', 'Proverbs', 19, 17, '&nbsp;څوک چې د غريب مدد کوى هغه مالِک خُدائ سره ښېګړه کوى او څۀ چې هغه کوى نو هغه به يې اجر ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15955, 'Proverbs 19:18', 'Proverbs', 19, 18, '&nbsp;د خپل زوئ تربيت د اول نه په ماشوموالى کښې کوه هسې نه چې وروستو تۀ د هغۀ ژوند برباد کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15956, 'Proverbs 19:19', 'Proverbs', 19, 19, '&nbsp;غصه ناک سړے به ضرور د خپلې غصې اَنجام ته ورسيږى، کۀ تاسو چرې هغه يو ځل بچ کړئ نو تاسو به هغه هر وخت بچ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15957, 'Proverbs 19:20', 'Proverbs', 19, 20, '&nbsp;نصيحت ته غوږ ونيسه او هدايت قبول کړه، نو په آخر کښې به تۀ هم هوښيار شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15958, 'Proverbs 19:21', 'Proverbs', 19, 21, '&nbsp;د انسان په زړۀ کښې ډيرې منصوبې وى، خو کيږى هغه څۀ چې د مالِک خُدائ رضا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15959, 'Proverbs 19:22', 'Proverbs', 19, 22, '&nbsp;وفادارى د انسان ښائست دے. يو غريب د دروغژن نه بهتر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15960, 'Proverbs 19:23', 'Proverbs', 19, 23, '&nbsp;د مالِک خُدائ يره د ژوندون سرچينه ده، کومه چې انسان ته سکون ورکوى او د مصيبتونو نه يې بچ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15961, 'Proverbs 19:24', 'Proverbs', 19, 24, '&nbsp;ناراسته خو خپل لاس تالى ته رسوى خو تر دې چې هغه بيا واپس خپلې خولې ته هم نۀ وړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15962, 'Proverbs 19:25', 'Proverbs', 19, 25, '&nbsp;کۀ څوک پېغور کوونکے ووهى نو د دې نه به ساده ګان سبق زده کړى، کۀ چرې پوهه سړے ورټلے شى نو هغه به د دې نه نور عِلم زده کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15963, 'Proverbs 19:26', 'Proverbs', 19, 26, '&nbsp;هر هغه څوک چې په خپل پلار باندې ظلم کوى او خپله مور وشړى نو دے هغه زوئ دے څوک چې د شرم باعث دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15964, 'Proverbs 19:27', 'Proverbs', 19, 27, '&nbsp;زما زويه هرکله چې تۀ نصيحت اورېدل بند کړې، نو تۀ به د عِلم د خبرو نه بې‌لارې شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15965, 'Proverbs 19:28', 'Proverbs', 19, 28, '&nbsp;بدکاره ګواه اِنصاف پورې خندا کوى، او بدکاران د شرارت نه خوند اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15966, 'Proverbs 19:29', 'Proverbs', 19, 29, '&nbsp;سزا د پېغور کوونکى دپاره تياره شوې وى، او وهل د کم عقلو د ملاګانو دپاره تيار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15967, 'Proverbs 20:1', 'Proverbs', 20, 1, '&nbsp;مے انسان نه مسخره کوونکے جوړوى او د شراب څښل د شر او فساد جرړه ده، هر هغه څوک چې په دې راواوړى نو هغه هوښيار نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15968, 'Proverbs 20:2', 'Proverbs', 20, 2, '&nbsp;د بادشاه غصه لکه د زمرى د غړمبېدو په شان وى، هر هغه څوک چې دے غصه کړى نو خپل ژوند په خطره کښې اچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15969, 'Proverbs 20:3', 'Proverbs', 20, 3, '&nbsp;د جنګ نه لرې کېدل انسان ته عزت ورکوى، خو هر کم عقل زر جنګ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15970, 'Proverbs 20:4', 'Proverbs', 20, 4, '&nbsp;ناراسته په صحيح موسم کښې قُلبه نۀ کوى نو د لو په وخت کښې هغۀ سره هيڅ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15971, 'Proverbs 20:5', 'Proverbs', 20, 5, '&nbsp;د انسان د زړۀ منصوبه د ډوبو اوبو په شان ده، خو هوښيار سړے ترې نه دا بهر راوباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15972, 'Proverbs 20:6', 'Proverbs', 20, 6, '&nbsp;ډېر خلق د وفادارۍ دعوې کوى، خو وفادار يو هم نۀ پېدا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15973, 'Proverbs 20:7', 'Proverbs', 20, 7, '&nbsp;صادقه انسان نېک ژوند تېروى او د هغۀ راروان نسل بختور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15974, 'Proverbs 20:8', 'Proverbs', 20, 8, '&nbsp;کله چې يو بادشاه د عدالت دپاره په تخت کښېنى، خو هغه په خپله د ټولو بدو تول کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15975, 'Proverbs 20:9', 'Proverbs', 20, 9, '&nbsp;څوک دا وئيلے شى چې، زما زړۀ صفا دے او زۀ پاک او بې‌ګناه يم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15976, 'Proverbs 20:10', 'Proverbs', 20, 10, '&nbsp;د غلط تول او غلط ناپ دواړو نه مالِک خُدائ نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15977, 'Proverbs 20:11', 'Proverbs', 20, 11, '&nbsp;ماشومان هم په خپل کردار پېژندلے شى، دا چې ولې د دوئ کردار پاک او ښۀ دے او کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15978, 'Proverbs 20:12', 'Proverbs', 20, 12, '&nbsp;غوږونه چې اورېدل او سترګې چې ليدل کوى مالِک خُدائ دا دواړه جوړ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15979, 'Proverbs 20:13', 'Proverbs', 20, 13, '&nbsp;خوب سره مينه مۀ کوه ځکه چې غريب به شې، بېدار اوسه نو تا سره به د خوراک دپاره هر څۀ ډېر تير وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15980, 'Proverbs 20:14', 'Proverbs', 20, 14, '&nbsp;اخستونکى تل دا شکايت کوى چې، ”دا ښۀ نۀ دے، دا ښۀ نۀ دے،“ نو بيا هغه لاړ شى او وائى چې، ”دا سودا مې ډېره ښۀ واخسته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15981, 'Proverbs 20:15', 'Proverbs', 20, 15, '&nbsp;سرۀ زر او لعلونه زيات پېدا کيږى، خو هغه شونډې چې د عقلمندۍ خبرې کوى نايابه زيورات دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15982, 'Proverbs 20:16', 'Proverbs', 20, 16, '&nbsp;هر څوک چې د پردى کس د قرض ذمه وارى اخلى نو ضمانت ترې نه واخله، ضمانت ترې نه واخله کۀ چرې دۀ دا کار د پردى کس دپاره کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15983, 'Proverbs 20:17', 'Proverbs', 20, 17, '&nbsp;د غلا روټۍ خوږه وى، خو دا په خولۀ کښې په باجرۍ بدليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15984, 'Proverbs 20:18', 'Proverbs', 20, 18, '&nbsp;د نصيحت په رڼا کښې منصوبې جوړوه، د جنګ نه وړاندې ښۀ مشوره کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15985, 'Proverbs 20:19', 'Proverbs', 20, 19, '&nbsp;غېبت راز څرګندوى، نو د هغه کس نه ځان ساته څوک چې مشروټى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15986, 'Proverbs 20:20', 'Proverbs', 20, 20, '&nbsp;کۀ يو انسان چرې په خپل مور پلار لعنت کوى، د هغۀ د ژوند چراغ به په توره تيارۀ کښې ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15987, 'Proverbs 20:21', 'Proverbs', 20, 21, '&nbsp;کوم ميراث چې انسان ته زر حاصل شى، نو په آخره کښې به هغه دۀ ته د برکت ذريعه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15988, 'Proverbs 20:22', 'Proverbs', 20, 22, '&nbsp;داسې مۀ وايه چې، ”د دې بدو انتقام به زۀ په خپله اخلم.“ مالِک خُدائ ته صبر وکړه هغه به ستا بدله واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15989, 'Proverbs 20:23', 'Proverbs', 20, 23, '&nbsp;مالِک خُدائ د غلط تول نه نفرت کوى، او د غلطى تلې استعمال بد کار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15990, 'Proverbs 20:24', 'Proverbs', 20, 24, '&nbsp;د انسان قدمونه اخستل مالِک خُدائ په خپله مقرر کړى دى، نو بيا به څنګه يو کس په خپله لار پوهه شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15991, 'Proverbs 20:25', 'Proverbs', 20, 25, '&nbsp;خپل ځان په بې‌سوچه نذر منلو سره خُدائ ته مۀ راګېروه، نو بيا کله چې وروستو په هغې باندې فکر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15992, 'Proverbs 20:26', 'Proverbs', 20, 26, '&nbsp;هوښيار بادشاه بدکاران په غاښۍ ولى، او په هغوئ باندې غوبل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15993, 'Proverbs 20:27', 'Proverbs', 20, 27, '&nbsp;د مالِک خُدائ رڼا د انسان د روح لټون کوى، او هغه د هغوئ په ځان کښې دننه لټون کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15994, 'Proverbs 20:28', 'Proverbs', 20, 28, '&nbsp;مينه او وفادارى يو بادشاه محفوظ ساتى، د مينې په وجه د هغۀ تخت به مدام قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15995, 'Proverbs 20:29', 'Proverbs', 20, 29, '&nbsp;د ځوانانو عزت او جلال د دوئ طاقت دے، سپين وېښتۀ د بوډاوالى شان و شوکت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15996, 'Proverbs 20:30', 'Proverbs', 20, 30, '&nbsp;زخمونه او دردونه بدکارى لرې کوى، وهل انسان دننه نه صفا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15997, 'Proverbs 21:1', 'Proverbs', 21, 1, '&nbsp;د بادشاه زړۀ د مالِک خُدائ په لاس کښې دے، کوم ځائ چې د دۀ خوښه وى هلته يې لکه د نِهرونو د اوبو غوندې بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15998, 'Proverbs 21:2', 'Proverbs', 21, 2, '&nbsp;هر سړى ته خپلې ټولې لارې په خپل نظر کښې صحيح ښکارى، خو مالِک خُدائ د زړُونو جاج اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15999, 'Proverbs 21:3', 'Proverbs', 21, 3, '&nbsp;صداقت او اِنصاف کول مالِک خُدائ دا د قربانۍ نه زيات خوښوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16000, 'Proverbs 21:4', 'Proverbs', 21, 4, '&nbsp;مغروره سترګې او مغرور زړۀ د بدعملو چراغ او ګناه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');